import sys
from collections import defaultdict

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def solve():
    try:
        lines = sys.stdin.read().splitlines()
    except Exception:
        return

    if not lines:
        return

    line_idx = 0
    while line_idx < len(lines) and not lines[line_idx].strip():
        line_idx += 1

    if line_idx >= len(lines):
        return

    try:
        n_k_line = lines[line_idx].strip()
        parts = n_k_line.split()
        n = int(parts[0])
        k = int(parts[1])
        line_idx += 1
    except (IndexError, ValueError):
        return

    if n == 0:
        print(0)
        return

    nodes = {}
    node_order = []

    if line_idx < len(lines):
        values_line = lines[line_idx].strip()
        values = list(map(int, values_line.split()))
        line_idx += 1
    else:
        values = []

    if len(values) != n:
        return

    for i in range(n):
        val = values[i]
        nodes[i] = Node(val)
        node_order.append(nodes[i])

    if line_idx < len(lines):
        edges_line = lines[line_idx].strip()
        edges = list(map(int, edges_line.split()))
        line_idx += 1
    else:
 edges = []

    if len(edges) != 2 * n:
        return

    for i in range(n):
        left_idx = edges[2 * i]
        right_idx = edges[2 * i + 1]

        if left_idx != -1:
            nodes[i].left = nodes[left_idx]
        if right_idx != -1:
            nodes[i].right = nodes[right_idx]

    root = nodes[0]
    MOD = 10**9 + 7

    prefix_sum_count = defaultdict(int)
    prefix_sum_count[0] = 1

    count = 0

    def dfs(node, current_prefix_sum):
        nonlocal count
        if node is None:
            return

        current_prefix_sum += node.val
        target = current_prefix_sum - k
        if target in prefix_sum_count:
            count = (count + prefix_sum_count[target]) % MOD

        prefix_sum_count[current_prefix_sum] += 1

        dfs(node.left, current_prefix_sum)
        dfs(node.right, current_prefix_sum)

        prefix_sum_count[current_prefix_sum] -= 1
        if prefix_sum_count[current_prefix_sum] == 0:
            del prefix_sum_count[current_prefix_sum]

    dfs(root, 0)
    print(count % MOD)

if __name__ == "__main__":
    solve()
